WITH flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM transactions), sessions_transactions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT CASE WHEN burst_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS burst_id_tier, SIZE(COLLECT_SET(merchant)) AS num_merchants, MIN(amount) AS min_amount, COUNT(*) FILTER (WHERE txn_type = 'FEE') AS fee_rows, COUNT(DISTINCT txn_type) AS distinct_txn_types, COUNT(CASE WHEN merchant = 'Shell' THEN 1 END) AS shell_count, COUNT(*) AS num_rows FROM sessions_transactions GROUP BY burst_id_tier;
